function hasConsent(){return!0}function getLocalStorage(key,def,category){return hasConsent(category)?localStorage.getItem(key):def}function setLocalStorage(key,val,category){hasConsent(category)&&localStorage.setItem(key,val)}function getSessionStorage(key,def,category){return hasConsent(category)?sessionStorage.getItem(key):def}function setSessionStorage(key,val,category){hasConsent(category)&&sessionStorage.setItem(key,val)}(function(){try{localStorage.getItem("sidebar-collapsed")==="1"&&document.documentElement.classList.add("sidebar-pre-collapsed")}catch{}})()